<?php
namespace Tests\Feature;
use Tests\TestCase;
use Illuminate\Foundation\Testing\RefreshDatabase;
use App\Models\{Tour,Booking,Contact,User,Review,TourImage};
use Illuminate\Http\UploadedFile;
use Illuminate\Support\Facades\Storage;
class TourismTest extends TestCase {
 use RefreshDatabase;
 protected function beforeRefreshingDatabase(): void {if(config('database.default')==='mysql'&&!str_ends_with(config('database.connections.mysql.database'),'_test'))throw new \RuntimeException('Tests autorisés uniquement dans une base suffixée _test.');}
 protected function setUp(): void {parent::setUp();$this->seed();}
 private function payload(array $extra=[]): array {$tour=Tour::first();return array_merge(['name'=>'Integration Traveller','email'=>'traveller@example.test','whatsapp'=>'+212600000000','tour_id'=>$tour->id,'tour_package_id'=>$tour->packages()->first()->id,'travel_date'=>today()->addDays(10)->toDateString(),'people'=>2,'pack'=>'Standard','request_type'=>'tour','consent'=>true],$extra);}
 private function admin(): User {return User::factory()->create(['is_admin'=>true]);}
 public function test_only_three_destinations_are_public_without_deleting_other_data(): void {
  // Seed an archived destination explicitly: fresh installations contain only the three public cities.
  \App\Models\Destination::create(['name'=>'Marrakech','slug'=>'marrakech','description'=>['fr'=>'Archive','en'=>'Archive'],'image'=>'/assets/archived.jpg']);
  $this->postJson('/api/bookings',$this->payload())->assertCreated();
  $tourCount=Tour::count();$bookingCount=Booking::count();$destinationCount=\App\Models\Destination::count();
  $response=$this->getJson('/api/destinations')->assertOk()->assertJsonCount(3);
  $this->assertSame(['Fès','Tanger','Casablanca'],array_column($response->json(),'name'));
  foreach($response->json() as $destination)$this->assertFileExists(dirname(base_path()).'/frontend/public'.$destination['image']);
  $this->assertDatabaseHas('destinations',['slug'=>'marrakech']);$this->assertSame($destinationCount,\App\Models\Destination::count());$this->assertSame($tourCount,Tour::count());$this->assertSame($bookingCount,Booking::count());
  $this->actingAs($this->admin())->getJson('/api/admin/destinations')->assertOk()->assertJsonCount($destinationCount,'data');
 }
 public function test_public_destination_links_include_departure_and_arrival_tours(): void {
  foreach(['Fès','Tanger','Casablanca'] as $city){$rows=$this->getJson('/api/tours?destination='.urlencode($city))->assertOk()->json();$this->assertNotEmpty($rows);foreach($rows as $tour)$this->assertTrue($tour['start_city']===$city||$tour['end_city']===$city||$tour['destination']['name']===$city);}
  $rows=$this->getJson('/api/tours?destination='.urlencode('Fès'))->assertOk()->json();$this->assertContains('fes-decouverte',array_column($rows,'slug'));
  $this->getJson('/api/tours?destination=Sahara')->assertOk()->assertJsonCount(0);
 }
 public function test_admin_rejects_invalid_programme_and_accepts_imported_structure(): void {$this->actingAs($this->admin());$tour=Tour::first();$this->putJson('/api/admin/tours/'.$tour->id,['content'=>['presentation'=>['fr'=>['days'=>'invalid']]]])->assertUnprocessable();$this->putJson('/api/admin/tours/'.$tour->id,['content'=>$tour->content])->assertOk();}
 public function test_original_catalogue_and_detail_are_available(): void {$this->getJson('/api/tours')->assertOk()->assertJsonCount(3);$this->getJson('/api/tours/fes-decouverte')->assertOk()->assertJsonPath('title.fr','Fès, à votre rythme')->assertJsonCount(3,'images');$this->getJson('/api/tours/absent')->assertNotFound();}
 public function test_catalogue_filters_are_applied_on_server(): void {$r=$this->getJson('/api/tours?city=F%C3%A8s&kind=culture&days=1')->assertOk();foreach($r->json() as $tour){$this->assertSame('Fès',$tour['start_city']);$this->assertSame('culture',$tour['kind']);$this->assertLessThanOrEqual(3,$tour['duration_days']);}$this->assertNotEmpty($r->json());$this->getJson('/api/tours?days=-1')->assertUnprocessable();$this->getJson('/api/tours?q=F%C3%A8s')->assertJsonCount(1);}
 public function test_booking_is_persisted_and_cannot_set_its_own_status_or_price(): void {$r=$this->postJson('/api/bookings',$this->payload(['status'=>'confirmed','final_quote'=>1]))->assertCreated()->assertJsonPath('status','pending');$this->assertDatabaseHas('bookings',['reference'=>$r->json('reference'),'status'=>'pending','final_quote'=>null,'people'=>2]);$this->assertSame(1,Booking::count());}
 public function test_invalid_booking_never_writes_a_row(): void {$this->postJson('/api/bookings',$this->payload(['travel_date'=>'2000-01-01','people'=>0,'email'=>'bad','consent'=>false]))->assertUnprocessable()->assertJsonValidationErrors(['travel_date','people','email','consent']);$this->assertDatabaseCount('bookings',0);}
 public function test_honeypot_and_other_tour_package_are_rejected(): void {$this->postJson('/api/bookings',$this->payload(['website'=>'https://spam.test']))->assertUnprocessable();$other=Tour::skip(1)->first();$this->postJson('/api/bookings',$this->payload(['tour_package_id'=>$other->packages()->first()->id]))->assertUnprocessable();$this->assertDatabaseCount('bookings',0);}
 public function test_capacity_is_checked_and_released_on_cancellation(): void {$tour=Tour::first();$tour->availabilities()->create(['date'=>today()->addDays(10),'capacity'=>2,'available'=>true]);$this->postJson('/api/bookings',$this->payload())->assertCreated();$this->postJson('/api/bookings',$this->payload(['people'=>1]))->assertUnprocessable()->assertJsonValidationErrors('travel_date');Booking::first()->update(['status'=>'cancelled']);$this->postJson('/api/bookings',$this->payload(['people'=>1]))->assertCreated();}
 public function test_unpublished_tours_and_closed_dates_are_rejected(): void {$tour=Tour::first();$tour->availabilities()->create(['date'=>today()->addDays(10),'capacity'=>20,'available'=>false]);$this->postJson('/api/bookings',$this->payload())->assertUnprocessable();$tour->update(['published'=>false]);$this->getJson('/api/tours/'.$tour->slug)->assertNotFound();$this->postJson('/api/bookings',$this->payload())->assertUnprocessable();}
 public function test_custom_and_student_requests_are_stored_without_a_tour(): void {foreach(['custom','students'] as $kind)$this->postJson('/api/bookings',$this->payload(['tour_id'=>null,'tour_package_id'=>null,'request_type'=>$kind,'duration'=>7,'options'=>['Airport transfer']]))->assertCreated();$this->assertDatabaseCount('bookings',2);}
 public function test_contact_is_saved_after_validation(): void {$this->postJson('/api/contacts',['name'=>'Traveller','email'=>'traveller@example.test','message'=>'Please send more information.','consent'=>true])->assertCreated();$this->assertDatabaseCount('contacts',1);$this->postJson('/api/contacts',['name'=>'Invalid'])->assertUnprocessable();$this->assertDatabaseCount('contacts',1);}
 public function test_guest_and_non_admin_cannot_read_or_modify_private_data(): void {$this->getJson('/api/admin/bookings')->assertUnauthorized();$this->postJson('/api/admin/tours',[])->assertUnauthorized();$this->actingAs(User::factory()->create())->getJson('/api/admin/stats')->assertForbidden();$this->actingAs(User::factory()->create())->putJson('/api/admin/tours/1',['published'=>false])->assertForbidden();}
 public function test_login_logout_and_non_admin_login(): void {$admin=$this->admin();$this->postJson('/login',['email'=>$admin->email,'password'=>'wrong'])->assertUnprocessable();$this->postJson('/login',['email'=>$admin->email,'password'=>'password'])->assertOk();$this->getJson('/api/admin/me')->assertOk();$this->postJson('/logout')->assertNoContent();$this->assertGuest('web');$regular=User::factory()->create();$this->postJson('/login',['email'=>$regular->email,'password'=>'password'])->assertForbidden();$this->assertGuest('web');}
 public function test_admin_tour_crud_and_destination_crud(): void {$this->actingAs($this->admin());$dest=$this->postJson('/api/admin/destinations',['name'=>'Test destination','slug'=>'test-destination','description'=>['fr'=>'Description','en'=>'Description'],'image'=>'/assets/atlas.jpg'])->assertCreated()->json();$tour=$this->postJson('/api/admin/tours',['slug'=>'test-tour','title'=>['fr'=>'Circuit test','en'=>'Test tour'],'description'=>['fr'=>'Description','en'=>'Description'],'start_city'=>'Marrakech','end_city'=>'Marrakech','duration_days'=>1,'kind'=>'private','destination_id'=>$dest['id'],'published'=>false])->assertCreated()->json();$this->putJson('/api/admin/tours/'.$tour['id'],['published'=>true])->assertOk();$this->getJson('/api/tours/test-tour')->assertNotFound();$this->deleteJson('/api/admin/tours/'.$tour['id'])->assertNoContent();$this->deleteJson('/api/admin/destinations/'.$dest['id'])->assertNoContent();}
 public function test_admin_can_process_bookings_and_cannot_delete_their_tour(): void {$this->postJson('/api/bookings',$this->payload())->assertCreated();$b=Booking::first();$this->actingAs($this->admin());$this->putJson('/api/admin/bookings/'.$b->id,['status'=>'confirmed','final_quote'=>1500,'currency'=>'EUR'])->assertOk();$this->assertDatabaseHas('bookings',['id'=>$b->id,'status'=>'confirmed','final_quote'=>1500]);$this->deleteJson('/api/admin/tours/'.$b->tour_id)->assertConflict();$this->getJson('/api/admin/stats')->assertJsonPath('confirmed',1);}
 public function test_packages_availability_reviews_and_social_settings(): void {$this->actingAs($this->admin());$this->postJson('/api/admin/packages',['tour_id'=>Tour::first()->id,'name'=>'Family','description'=>'On request'])->assertCreated();$this->postJson('/api/admin/availabilities',['tour_id'=>Tour::first()->id,'date'=>today()->addDay()->toDateString(),'capacity'=>10,'available'=>true])->assertCreated();$this->postJson('/api/admin/reviews',['name'=>'Sample','text'=>['fr'=>'Exemple','en'=>'Sample'],'rating'=>4,'is_demo'=>true,'published'=>true])->assertCreated();$this->putJson('/api/admin/settings',['instagram'=>'https://evil.test/profile'])->assertUnprocessable();$this->putJson('/api/admin/settings',['instagram'=>'https://www.instagram.com/moroway','home_tagline_fr'=>'Votre Maroc'])->assertOk();$this->getJson('/api/settings')->assertJsonPath('home_tagline_fr','Votre Maroc');foreach($this->getJson('/api/reviews')->assertOk()->json() as $review)$this->assertTrue($review['is_demo']);}
 public function test_uploads_reject_svg_and_store_valid_images(): void {$this->actingAs($this->admin());Storage::fake('public');$this->postJson('/api/admin/tours/'.Tour::first()->id.'/images',['image'=>UploadedFile::fake()->create('bad.svg',1,'image/svg+xml'),'alt'=>'Bad'])->assertUnprocessable();$file=new UploadedFile(dirname(base_path()).'/frontend/public/assets/moroway-camel-logo.png','photo.png','image/png',null,true);$r=$this->postJson('/api/admin/tours/'.Tour::first()->id.'/images',['image'=>$file,'alt'=>'MOROWAY TOURS'])->assertCreated();$path=substr($r->json('path'),9);Storage::disk('public')->assertExists($path);$this->deleteJson('/api/admin/images/'.$r->json('id'))->assertNoContent();Storage::disk('public')->assertMissing($path);}
 public function test_login_and_submission_rate_limits(): void {for($i=0;$i<5;$i++)$this->postJson('/login',['email'=>'absent@example.test','password'=>'wrong'])->assertUnprocessable();$this->postJson('/login',['email'=>'absent@example.test','password'=>'wrong'])->assertTooManyRequests();for($i=0;$i<5;$i++)$this->postJson('/api/contacts',[])->assertUnprocessable();$this->postJson('/api/contacts',[])->assertTooManyRequests();}
 public function test_sitemap_contains_published_clean_routes(): void {$this->get('/sitemap.xml')->assertOk()->assertSee('/tours/fes-decouverte',false)->assertDontSee('/admin',false);}
}
